class Solution{String lo,hi;int c;char[][]p={{'0','0'},{'1','1'},{'6','9'},{'8','8'},{'9','6'}};void f(char[]s,int l,int r){if(l>r){String x=new String(s);if((x.length()>lo.length()||x.compareTo(lo)>=0)&&(x.length()<hi.length()||x.compareTo(hi)<=0))c++;return;}for(char[]q:p){if(l==0&&s.length>1&&q[0]=='0')continue;if(l==r&&q[0]!=q[1])continue;s[l]=q[0];s[r]=q[1];f(s,l+1,r-1);}}public int strobogrammaticInRange(String low,String high){lo=low;hi=high;for(int n=lo.length();n<=hi.length();n++)f(new char[n],0,n-1);return c;}}
